import java.io.*;
import java.util.*;

public classTwentyFive {
    public static void main(String[] args) throws Exception {
        Scanner scanner = new Scanner(System.in);
        String s = scanner.next();
        scanner.close();

        int result = 0;
        for (int n = 0; n < 100_000_000; n += 25) {
            String candidate = String.format("%08d", n);
            if (candidate.length() != s.length()) continue;

            boolean valid = true;
            char xChar = 0;
            boolean xDefined = false;

            for (int i = 0; i < s.length(); i++) {
                char sc = s.charAt(i);
                char cc = candidate.charAt(i);

                if (sc == 'X') {
                    if (!xDefined) {
                        xChar = cc;
                        xDefined = true;
                    } else if (cc != xChar) {
                        valid = false;
                        break;
                    }
                } else if (sc != '_') {
                    if (cc != sc) {
                        valid = false;
                        break;
                    }
                }
            }

            if (valid) result++;
        }

        System.out.println(result);
    }
}
